import re

# Get all TRG data for P81-P128 from supp.pdf page11
trg_rows = get_rows("supp.pdf", "page11")
trg_map = {}
for row_idx, row in enumerate(trg_rows, 1):
    if not row or len(row) < 8:
        continue
    patient_id = row[0]
    trg_val = row[7].lower()
    match = re.match(r"Patient-(\d+)", patient_id)
    if match:
        pid = int(match.group(1))
        if 81 <= pid <= 128:
            # Map truth: 0,1,ccr -> 1 (good response), 2,3 -> 0 (poor response)
            truth = 1 if trg_val in {"0", "1", "ccr"} else 0
            trg_map[pid] = {
                "truth": truth,
                "ref": f"supp.pdf/page11/R{row_idx}C8"
            }

# Get organoid combined treatment ratio for P81-P128 from supp.pdf page13 (rows 41-44) and page14 (all rows)
ratio_rows_p13 = get_rows("supp.pdf", "page13")
ratio_rows_p14 = get_rows("supp.pdf", "page14")
ratio_rows = ratio_rows_p13 + ratio_rows_p14
ratio_map = {}
for row_idx, row in enumerate(ratio_rows, 1):
    if not row or len(row) < 5:
        continue
    patient_id = row[0]
    ratio_val = row[4]
    match = re.match(r"Patient(\d+)", patient_id)
    if match:
        pid = int(match.group(1))
        if 81 <= pid <= 128:
            try:
                ratio = float(ratio_val)
                # Score: <= 0.3487 -> 1 (sensitive), > -> 0 (resistant)
                score = 1 if ratio <= 0.3487 else 0
                sheet = "page13" if row_idx <= len(ratio_rows_p13) else "page14"
                row_in_sheet = row_idx if sheet == "page13" else row_idx - len(ratio_rows_p13)
                ratio_map[pid] = {
                    "score": score,
                    "ref": f"supp.pdf/{sheet}/R{row_in_sheet}C5",
                    "ratio": ratio
                }
            except ValueError:
                pass

# Merge to create records, ensure 48 patients
records = []
correct = 0
for pid in range(81, 129):
    if pid not in trg_map or pid not in ratio_map:
        continue
    records.append({
        "id": f"P{pid}",
        "score": {
            "ref": ratio_map[pid]["ref"],
            "threshold": 0.3487,
            "op": "<="
        },
        "truth": {
            "ref": trg_map[pid]["ref"],
            "map": {"0": 1, "1": 1, "ccr": 1, "2": 0, "3": 0}
        }
    })
    if trg_map[pid]["truth"] == ratio_map[pid]["score"]:
        correct += 1

accuracy = correct / len(records) if records else 0.0

CONTRACT = {
    "status": "computed",
    "fields": {
        "unit": {"value": "patient", "evidence": ["article:p16"], "explanation": "Each record is a unique LARC patient in the validation cohort (P81-P128)"},
        "platform": {"value": "organoid", "evidence": ["article:p16"], "explanation": "Patient-derived rectal cancer organoids (RCOs) used for assay"},
        "readout": {"value": "size_viability", "evidence": ["article:p16"], "explanation": "Assay readout is ratio of organoid size on day 24 post-combined chemoradiation to day 0"},
        "direction": {"value": "lower_sensitive", "evidence": ["article:p16"], "explanation": "Lower size ratio indicates higher sensitivity to combined chemoradiation"},
        "threshold_rule": {"value": "fixed_numeric", "evidence": ["article:p16"], "explanation": "Fixed cutoff of 0.3487 size change ratio, derived from discovery cohort"},
        "threshold_timing": {"value": "independent_reference", "evidence": ["article:p16"], "explanation": "Threshold was pre-specified using the separate discovery cohort, not optimized on validation cohort"},
        "patient_mapping": {"value": "individual_available", "evidence": ["article:p16", "article:p72"], "explanation": "One-to-one mapping between organoid lines and patients, clinical outcomes available for all 48 validation patients"},
        "regimen_match": {"value": "matched", "evidence": ["article:p28"], "explanation": "Organoids were treated with the same combined chemoradiation regimen as patients"},
        "n_units": {"value": 48, "evidence": ["article:p16", "article:p28"], "explanation": "Total 48 patients in the validation cohort"},
        "split": {"value": "independent_test", "evidence": ["article:p16"], "explanation": "Validation cohort is separate from the discovery cohort used to set the threshold"}
    },
    "headline": {
        "metric": "accuracy",
        "reported": 0.9375,
        "reported_evidence": ["article:p28"],
        "threshold": 0.3487,
        "op": "<=",
        "score_direction": "higher",
        "records": records,
        "blocked_reason": None
    },
    "notes": [f"Computed accuracy: {accuracy:.4f}, correct classifications: {correct}, total records: {len(records)}"]
}

print(f"Accuracy check: {accuracy} == 0.9375? {abs(accuracy - 0.9375) < 1e-6}")
print(f"Missing PIDs: {[pid for pid in range(81, 129) if pid not in trg_map or pid not in ratio_map]}")
